let padSize={w:0,h:0},padObserver=null;
function setupPad(){padObserver?.disconnect();let canvas=$('#pad');strokesById[state.id]??=[];const resize=()=>{let r=canvas.getBoundingClientRect();padSize={w:r.width,h:r.height};const d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);drawPad()};padObserver=new ResizeObserver(resize);padObserver.observe(canvas);resize();let pointer=null;
 const point=e=>{let r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}};
 canvas.onpointerdown=e=>{if(pointer!==null)return;e.preventDefault();pointer=e.pointerId;canvas.setPointerCapture(pointer);currentStroke={color:pen,points:[point(e)]};strokesById[state.id].push(currentStroke);drawPad()};
 canvas.onpointermove=e=>{if(e.pointerId!==pointer||!currentStroke)return;e.preventDefault();for(const p of (e.getCoalescedEvents?.().length?e.getCoalescedEvents():[e]))currentStroke.points.push(point(p));drawPad()};
 const end=e=>{if(e.pointerId!==pointer)return;if(currentStroke?.points.length>4){mark('wrote');setHint(t('Lovely! Try it once more, or tap Next.','很棒！再寫一次，或按「下一步」。'));}pointer=null;currentStroke=null};canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onlostpointercapture=end;
}
function drawPad(){let canvas=$('#pad');if(!canvas)return;let {w,h}=padSize;if(!w||!h)return;let ctx=canvas.getContext('2d'),d=devicePixelRatio||1;ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#fffefa';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#e5e8dc';ctx.lineWidth=1;ctx.setLineDash([5,7]);for(let y of [.22,.50,.78]){ctx.beginPath();ctx.moveTo(0,h*y);ctx.lineTo(w,h*y);ctx.stroke()}ctx.beginPath();ctx.moveTo(w*.5,0);ctx.lineTo(w*.5,h);ctx.stroke();ctx.setLineDash([]);if(state.stage==='trace'){ctx.fillStyle='#e8ecdf';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`500 ${h*.72}px "Noto Sans Thai", Tahoma, sans-serif`;ctx.fillText(L().char,w*.5,h*.50)}if(state.stage==='copy'){ctx.fillStyle='#a3ad91';ctx.font=`500 ${h*.19}px "Noto Sans Thai", Tahoma, sans-serif`;ctx.textAlign='left';ctx.textBaseline='top';ctx.fillText(L().char,14,10)}for(let s of strokesById[state.id]||[]){ctx.strokeStyle=s.color;ctx.lineWidth=Math.max(4,w*.014);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(p.x*w,p.y*h):ctx.moveTo(p.x*w,p.y*h));if(s.points.length===1){ctx.lineTo(s.points[0].x*w+.1,s.points[0].y*h)}ctx.stroke()}}
function saveDrawing(){const src=$('#pad');if(!src)return;let out=document.createElement('canvas');out.width=src.width;out.height=src.height+100;let ctx=out.getContext('2d');ctx.fillStyle='#fffefa';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(src,0,80);ctx.fillStyle='#536b3d';ctx.font='30px sans-serif';ctx.fillText(`Thai Sprout · ${L().char} ${L().word}`,24,48);out.toBlob(blob=>{let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`my-thai-letter-${state.id}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast(t('Your writing picture is ready to save.','你的手寫圖片已準備好儲存。'))},'image/png')}
let demoImage=null,demoId=null;
function loadDemo(){if(!meta[state.id])return;demoId=state.id;demoImage=new Image();demoImage.onload=paintDemo;demoImage.src=`assets/writing-${state.id}.png`}
function paintDemo(){let canvas=$('#demo'),m=meta[state.id];if(!canvas||!m||!demoImage?.complete||demoId!==state.id)return;let ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);let s=Math.min(canvas.width/m.width,canvas.height/m.height),w=m.width*s,h=m.height*s;ctx.drawImage(demoImage,(demoFrame%m.frames)*m.width,0,m.width,m.height,(canvas.width-w)/2,(canvas.height-h)/2,w,h)}
let prev=0;function tick(now){let dt=Math.min(100,now-prev);prev=now;if(!document.hidden){if(artPlaying){artTime+=dt;$$('.art-character').forEach(g=>{let a=artTime/800;g.setAttribute('transform',`translate(0 ${Math.sin(a)*3.5}) rotate(${Math.sin(a*.7)*1.4} 160 180)`)})}let m=meta[state.id];if($('#demo')&&m&&demoPlaying){demoTime+=dt;let duration=(m.durations[demoFrame]||100)*(slow?2:1);if(demoTime>=duration){demoTime=0;demoFrame=(demoFrame+1)%m.frames;paintDemo()}}}requestAnimationFrame(tick)}
